/**
 * A fixed corpus and its golden set.
 *
 * Handwritten rather than generated, because a golden set generated by the same
 * family of model that answers the questions measures agreement, not retrieval.
 *
 * The questions are chosen to exercise specific failure modes, not to be easy:
 *   - near-duplicate sections that differ by one qualifier (EU vs US refunds)
 *   - answers that live in a table, not prose
 *   - a question whose wording shares no content words with its answer
 *   - rare exact tokens that dense retrieval blurs and BM25 nails (SAML, SOC 2)
 *   - out-of-scope questions that MUST return nothing
 */

export const CORPUS = `# Northwind Support Handbook

## Billing

Billing runs on a monthly cycle. Invoices are generated on the first of each month and emailed to the billing contact on the account.

### Payment methods

We accept Visa, Mastercard and American Express. ACH transfer is available on annual plans only. We do not accept cryptocurrency.

### Refunds

Refund eligibility depends on the customer's region and is governed by local consumer law.

#### EU refunds

EU customers may request a full refund within 14 days of purchase, under distance selling regulations. No reason is required. Refunds are returned to the original payment method within 5 business days.

#### US refunds

US customers may request a refund within 30 days of purchase. After 30 days, refunds are issued as account credit rather than to the original payment method.

### Failed payments

If a payment fails we retry three times over seven days. After the third failure the workspace moves to read-only. Data is retained for 90 days before deletion.

## Plans and limits

| Plan | Seats | Monthly messages | Support |
| --- | --- | --- | --- |
| Starter | 3 | 2,000 | Email |
| Team | 25 | 50,000 | Email and chat |
| Enterprise | Unlimited | 500,000 | Dedicated engineer |

Overage on the Team plan is billed at two cents per message. Starter plans hard-stop at the limit rather than billing overage.

## Onboarding

### Installing the CLI

Install with npm, then run the init command in your project root. The CLI requires Node 20 or later.

### Connecting a data source

Connect a source from the dashboard under Sources. Supported sources are Postgres, S3, and any public HTTPS endpoint returning JSON.

### First sync

The first sync typically completes in under ten minutes for datasets below one million rows. Larger datasets are processed in the background and you will be emailed on completion.

## Security

### Single sign-on

Single sign-on is available on Enterprise plans via SAML 2.0 and OIDC. We support Okta, Entra ID, and Google Workspace as identity providers.

### Compliance

We hold SOC 2 Type II certification, audited annually. Our most recent report is available under NDA from the trust portal.

### Data residency

Data is stored in the region selected at workspace creation. Available regions are us-east-1, eu-west-1 and ap-south-1. Region cannot be changed after creation.

### Encryption

Data is encrypted at rest with AES-256 and in transit with TLS 1.3. Customer-managed keys are available on Enterprise plans.

## Support

### Response times

Starter plans receive a response within two business days. Team plans within four business hours. Enterprise customers have a one-hour response target for production-down incidents.

### Escalation

To escalate an incident, reply to the ticket with the word ESCALATE in the subject line. This pages the on-call engineer directly.

## Account management

### Adding teammates

Workspace owners can invite teammates from Settings. Invitations expire after seven days.

### Deleting a workspace

Deleting a workspace is irreversible and removes all data immediately. Only the workspace owner can delete a workspace, and it requires typing the workspace name to confirm.
`;

export interface GoldenQuestion {
  question: string;
  /** Substrings that identify the chunk(s) a correct answer must retrieve. */
  expect: string[];
  /** What this question is testing. Printed in the per-question report. */
  probes: string;
  /** True when retrieval SHOULD come back empty and the gate should fire. */
  outOfScope?: boolean;
}

export const GOLDEN: GoldenQuestion[] = [
  { question: "How long do EU customers have to request a refund?",
    expect: ["14 days"], probes: "near-duplicate sections — must not return the US one" },
  { question: "How long do US customers have to request a refund?",
    expect: ["30 days"], probes: "the other side of the same near-duplicate" },
  { question: "What happens if my card is declined?",
    expect: ["retry three times"], probes: "no content words shared with the answer" },
  { question: "How many messages does the Team plan include?",
    expect: ["| Team | 25 | 50,000"], probes: "answer lives in a table row" },
  { question: "What is charged for going over the message limit?",
    expect: ["two cents per message"], probes: "prose adjacent to a table" },
  { question: "Which identity providers work with SSO?",
    expect: ["Okta"], probes: "rare exact tokens (SAML, Okta) that favour BM25" },
  { question: "Are you SOC 2 certified?",
    expect: ["SOC 2 Type II"], probes: "rare token, near-verbatim match" },
  { question: "Can I move my data to a different region later?",
    expect: ["cannot be changed after creation"], probes: "negation — the answer is a refusal" },
  { question: "What encryption do you use?",
    expect: ["AES-256"], probes: "straightforward lookup" },
  { question: "How do I get a production incident looked at urgently?",
    expect: ["ESCALATE"], probes: "paraphrase of a procedure" },
  { question: "What version of Node do I need?",
    expect: ["Node 20"], probes: "specific version number" },
  { question: "How long does the first sync take?",
    expect: ["under ten minutes"], probes: "straightforward lookup" },
  { question: "What happens to my data if I stop paying?",
    expect: ["read-only", "90 days"], probes: "answer spans two sentences of one chunk" },
  { question: "How long do invitations last?",
    expect: ["expire after seven days"], probes: "short factual detail in a small section" },
  { question: "Can I pay by bank transfer?",
    expect: ["ACH transfer"], probes: "synonym — 'bank transfer' vs 'ACH'" },
  { question: "Is deleting a workspace reversible?",
    expect: ["irreversible"], probes: "yes/no answered by a single word" },
  { question: "What is the capital of France?",
    expect: [], probes: "out of scope — the gate must fire", outOfScope: true },
  { question: "Write me a Python script to sort a list.",
    expect: [], probes: "off-purpose — the gate must fire", outOfScope: true },
  { question: "What is your CEO's home address?",
    expect: [], probes: "out of scope and adversarial", outOfScope: true },
];

/**
 * Distractor corpus.
 *
 * Without this the harness cannot measure anything: the handbook alone chunks to
 * well under CANDIDATE_K, so every retriever returns the ENTIRE corpus and
 * recall@5 saturates at 1.000 for every configuration. An ablation where every
 * row scores identically is not an ablation.
 *
 * These are deliberately CONFUSABLE, not filler — a deprecated v1 handbook with
 * the same structure and contradictory numbers, plus a partner handbook using
 * the same vocabulary for a different product. A retriever that matches on
 * vocabulary alone will happily return "7 days" for the EU refund window, which
 * is exactly the production failure worth measuring: stale and adjacent
 * documents living in the same knowledge base as the current one.
 */
